using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace CastleFight {
public sealed partial class PcGame {
    JObject finalFxIndex,finalSizes;readonly Dictionary<string,GameObject> finalFxPrefabs=new Dictionary<string,GameObject>();readonly Dictionary<string,PcModel> finalAttachments=new Dictionary<string,PcModel>();readonly Dictionary<Color,Material> finalDetailMaterials=new Dictionary<Color,Material>();readonly HashSet<PcModel> finalDecorated=new HashSet<PcModel>();
    void LoadFinalArt(){if(finalFxIndex!=null)return;var asset=ContentResources.Load<TextAsset>("final-fx-index");finalFxIndex=asset?JObject.Parse(asset.text):new JObject();asset=ContentResources.Load<TextAsset>("port-model-sizes");finalSizes=asset?JObject.Parse(asset.text):new JObject();}
    float FinalMarkerHeight(string raw){LoadFinalArt();var cfg=finalSizes[raw];return cfg!=null?HumanMatch.F(cfg,"marker_height",HumanMatch.F(cfg,"height",3.15f))+.35f:3.5f;}
    GameObject FinalFx(string key,int team){if(string.IsNullOrEmpty(key))return null;string id=key+"-"+team;if(!finalFxPrefabs.TryGetValue(id,out var value)){value=ContentResources.Load<GameObject>("FinalFx/"+id);finalFxPrefabs[id]=value;}return value;}
    void ResolveFinalDefaultColors(){LoadFinalArt();foreach(var p in (finalFxIndex["defaultWhite"] as JObject??new JObject()).Properties())for(int team=0;team<2;team++){var prefab=FinalFx(p.Name,team);if(prefab)foreach(var skin in prefab.GetComponentsInChildren<SkinnedMeshRenderer>())foreach(int i in (JArray)p.Value){var mat=skin.sharedMaterials[i];if(mat&&!mat.mainTexture)mat.mainTexture=Texture2D.whiteTexture;}}}
    GameObject FinalMissile(HumanMatch.Shot shot){LoadFinalArt();string missile=shot.weapon?.missile??"",key=null;if(missile.StartsWith("final:",StringComparison.Ordinal))key=missile.Substring(6);else if(missile.StartsWith("elven:",StringComparison.Ordinal))key=(string)finalFxIndex["visuals"]?[missile.Substring(6)]?["missile"]?[0]?["key"];else if(shot.line>=0&&shot.line<match.Lines.Length){string raw=shot.sourceId>=0?match.Units.FirstOrDefault(u=>u.id==shot.sourceId) is HumanMatch.Unit u?match.Lines[u.kind].unit:null:null;key=(string)finalFxIndex["weapons"]?[raw+"_1"]??(string)finalFxIndex["weapons"]?[match.Lines[shot.line].building+"_1"]??(string)finalFxIndex["weapons"]?[match.Lines[shot.line].unit+"_1"];}return FinalFx(key,shot.team);}
    void PlaceFinal(HashSet<string> wanted,string id,string key,int team,Vector3 point,Vector2 heading=default){var prefab=FinalFx(key,team);if(!prefab)return;wanted.Add(id);if(!finalAttachments.TryGetValue(id,out var model)||!model||model.raw!=key){if(model)Destroy(model.gameObject);model=Instantiate(prefab,visuals.transform).GetComponent<PcModel>();if(!model.particleOnly&&model.clips.Length>0)model.Play(model.clips.Any(c=>c.name.StartsWith("Stand",StringComparison.OrdinalIgnoreCase))?"Stand":model.clips[0].name);finalAttachments[id]=model;}model.transform.position=point;if(heading.sqrMagnitude>0)model.Face(heading);}
    Vector3 FinalAnchor(PcModel view,string attachment){var tokens=(attachment??"origin").ToLowerInvariant().Split(new[]{',',' '},StringSplitOptions.RemoveEmptyEntries);var p=(finalFxIndex["attachments"]?[view.raw]?["points"] as JArray??new JArray()).FirstOrDefault(v=>tokens.All(t=>((string)v["name"]).ToLowerInvariant().Contains(t)));if(p==null)return view.transform.position;var offset=(JArray)p["offset"];var v=new Vector3(-(float)offset[0],(float)offset[1],(float)offset[2]);var bone=view.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name==(string)p["bone"]);return bone?bone.TransformPoint(v):view.animatedRoot.transform.TransformPoint(v);}
    void FinalBuff(HashSet<string> wanted,string prefix,PcModel view,int team,string id){int index=0;foreach(var art in finalFxIndex["visuals"]?[id]?["buff"] as JArray??new JArray())PlaceFinal(wanted,prefix+"-"+id+"-"+index++,(string)art["key"],team,FinalAnchor(view,(string)art["attach"]));}
    void RenderFinalEffects(){LoadFinalArt();var wanted=new HashSet<string>();foreach(var u in match.Units)if(u.hp>0&&match.NightCanDetect(0,u)&&units.TryGetValue(u.id,out var view)){if(!finalDecorated.Contains(view))DecorateFinal(view,u.team,false);foreach(string id in u.abilities.Where(id=>NativePersistentArt(u,id)).Concat(u.auraIds).Concat(u.effects.Where(e=>e.left>0).Select(e=>e.id)).Distinct())FinalBuff(wanted,"unit-"+u.id,view,u.team,id);int race=u.team==0?matchRace:matchBotRace;if(selectedUnit==u.id&&race>=12&&match.Aspects[u.team]>=0){var cfg=AspectOptions(race)?[match.Aspects[u.team]];PlaceFinal(wanted,"aspect-"+u.id,(string)cfg?["visual"]?["buff"]?["key"],u.team,view.transform.position);}}
        foreach(var h in match.Huts)if(huts.TryGetValue(h.id,out var view)&&!finalDecorated.Contains(view))DecorateFinal(view,h.team,true);
        foreach(var keg in match.PandaKegs)PlaceFinal(wanted,"keg-"+keg.id,"panda_keg",keg.team,World(keg.point)+Vector3.up*.65f,keg.heading);
        foreach(var pulse in match.Pulses)if((pulse.fx??"").StartsWith("final:",StringComparison.Ordinal)){var parts=pulse.fx.Split(':');if(parts.Length!=3)continue;int index=0;foreach(var art in finalFxIndex["visuals"]?[parts[1]]?[parts[2]] as JArray??new JArray())PlaceFinal(wanted,"pulse-"+pulse.id+"-"+index++,(string)art["key"],0,World(pulse.position));}
        foreach(string id in finalAttachments.Keys.Where(id=>!wanted.Contains(id)).ToArray()){if(finalAttachments[id])Destroy(finalAttachments[id].gameObject);finalAttachments.Remove(id);}
    }
    void FinalPart(Transform parent,PrimitiveType type,Vector3 position,Vector3 scale,Color color){var obj=GameObject.CreatePrimitive(type);obj.name="Source Pandaren detail";Destroy(obj.GetComponent<Collider>());obj.transform.SetParent(parent,false);obj.transform.localPosition=position;obj.transform.localScale=scale;var renderer=obj.GetComponent<Renderer>();if(!finalDetailMaterials.TryGetValue(color,out var material)){material=new Material(Shader.Find("CastleFight/NativeUnit")){mainTexture=Texture2D.whiteTexture};material.SetColor("_Tint",color);finalDetailMaterials[color]=material;}renderer.sharedMaterial=material;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}
    void DecorateFinal(PcModel view,int team,bool building){finalDecorated.Add(view);string raw=view.raw;if(!raw.StartsWith("nP0",StringComparison.Ordinal)&&!raw.StartsWith("p",StringComparison.Ordinal))return;var parent=new GameObject("PandarenDetails").transform;parent.SetParent(view.transform,false);
        if(!building&&new[]{"nP02","nP04","nP06","nP08","nP0A","nP0C"}.Contains(raw)){var bone=view.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name.ToLowerInvariant().Contains("chest")||t.name.ToLowerInvariant().Contains("spine2"));parent.SetParent(bone?bone:view.animatedRoot.transform,false);if(!bone)parent.localPosition=Vector3.up*1.4f;for(int i=0;i<9;i++){float angle=Mathf.PI*2*i/9;FinalPart(parent,PrimitiveType.Sphere,new Vector3(Mathf.Sin(angle)*.31f,-.12f,Mathf.Cos(angle)*.25f),Vector3.one*.13f,new Color(.369f,.663f,.514f));}foreach(int sign in new[]{-1,1})FinalPart(parent,PrimitiveType.Cube,new Vector3(sign*.37f,.04f,0),new Vector3(.29f,.09f,.38f),new Color(.702f,.561f,.302f));}
        else if(building){float scale=HumanMatch.F(finalFxIndex["buildingScales"],raw,1);parent.localScale=Vector3.one*scale;if(raw=="pT01"||raw=="pT02"){var prefab=FinalFx("panda_dragon",team);if(prefab){var dragon=Instantiate(prefab,parent).GetComponent<PcModel>();StaticPandaDragon(dragon);dragon.transform.localPosition=Vector3.up*3.35f;dragon.transform.localRotation=Quaternion.Euler(0,90,0);dragon.transform.localScale=Vector3.one*(raw=="pT02"?1.12f:1);}}else if(raw=="pK01")foreach(int side in new[]{-1,1}){FinalPart(parent,PrimitiveType.Cube,new Vector3(0,.3f,side*1.1f),new Vector3(3.2f,.3f,.4f),new Color(.31f,.208f,.125f));foreach(int end in new[]{-1,1})FinalPart(parent,PrimitiveType.Cube,new Vector3(end*1.1f,.65f,side*1.1f),new Vector3(.35f,1.5f,.35f),new Color(.431f,.298f,.169f));}}
    }
    // Godot instantiates this decoration as a plain static GLB; it has no skin.
    // Draw its original mesh directly rather than applying the runtime effect skin adapter.
    void StaticPandaDragon(PcModel dragon){
        dragon.particleOnly=true;
        foreach(var animation in dragon.GetComponentsInChildren<Animation>()){animation.Stop();animation.enabled=false;}
        foreach(var appearance in dragon.GetComponentsInChildren<NativeAppearance>()){appearance.enabled=false;Destroy(appearance);}
        foreach(var skin in dragon.GetComponentsInChildren<SkinnedMeshRenderer>()){
            var part=new GameObject("Source static jade dragon");part.transform.SetParent(skin.transform,false);
            part.AddComponent<MeshFilter>().sharedMesh=skin.sharedMesh;
            var renderer=part.AddComponent<MeshRenderer>();renderer.sharedMaterials=skin.sharedMaterials;skin.enabled=false;
        }
    }
    void AuditFinalParticles(){int count=0;foreach(var prefab in ContentResources.LoadAll<GameObject>("FinalFx").Concat(nerubianPack?nerubianPack.Prefabs:Enumerable.Empty<GameObject>()).Concat(pandarenPack?pandarenPack.Prefabs:Enumerable.Empty<GameObject>()))foreach(var renderer in prefab.GetComponentsInChildren<ParticleSystemRenderer>()){var m=renderer.sharedMaterial;if(!m||!m.mainTexture||!m.shader||!m.shader.isSupported)throw new InvalidOperationException("Invalid final particle material "+prefab.name);count++;}Debug.Log("CF_FINAL_PARTICLE_AUDIT_PASS materials="+count);}
    void ClearFinalViews(){finalAttachments.Clear();finalDecorated.Clear();foreach(var material in finalDetailMaterials.Values)if(material)Destroy(material);finalDetailMaterials.Clear();}
}
}
